package com.bank.fraud;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FraudScanDemo {
    private static final Logger log = Logger.getLogger(FraudScanDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Threshold: any single transaction above Rs.500000 is suspicious.
        BigDecimal threshold = new BigDecimal("500000.00");

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        // Branch MUM01 has a reversal (skipped) and two normal transactions.
        Branch mumbai = new Branch("MUM01", List.of(
                new Transaction("TXN-1", rajesh.getAccountId(), new BigDecimal("-20000.00"), "REVERSAL"),
                new Transaction("TXN-2", rajesh.getAccountId(), new BigDecimal("45000.00"), "TRANSFER"),
                new Transaction("TXN-3", priya.getAccountId(),  new BigDecimal("12000.00"), "TRANSFER")
        ));

        // Branch DEL02 contains one suspicious transaction above the threshold.
        Branch delhi = new Branch("DEL02", List.of(
                new Transaction("TXN-4", priya.getAccountId(),  new BigDecimal("30000.00"),  "TRANSFER"),
                new Transaction("TXN-5", rajesh.getAccountId(), new BigDecimal("750000.00"), "TRANSFER")
        ));

        FraudScanService service = new FraudScanService(threshold);
        Transaction found = service.scanForFraud(List.of(mumbai, delhi));

        if (found != null) {
            log.severe(() -> "BATCH HALTED: suspicious txn " + found.getId()
                    + " amount=" + found.getAmount());
        } else {
            log.info("Scan clean — settlement may proceed.");
        }
    }
}

