// ─── Would be in service/FraudScanService.java in a real project ───
class FraudScanService {
    private static final Logger log = Logger.getLogger(FraudScanService.class.getName());
    private final BigDecimal threshold;

    FraudScanService(BigDecimal threshold) { this.threshold = threshold; }

    // Outer loop over branches, inner loop over transactions.
    // continue  -> skip a reversal without stopping the scan.
    // break scan -> abort the ENTIRE nested scan when fraud is found.
    Transaction scanForFraud(java.util.List<Branch> branches) {
        Transaction suspicious = null;

        scan:
        for (Branch branch : branches) {                 // outer loop
            log.info(() -> "Scanning branch " + branch.getCode());
            for (Transaction txn : branch.getTransactions()) {   // inner loop
                if ("REVERSAL".equals(txn.getType())) {
                    log.fine(() -> "Skipping reversal " + txn.getId());
                    continue;                            // skip only this txn
                }
                if (txn.getAmount().abs().compareTo(threshold) > 0) {
                    suspicious = txn;
                    log.warning(() -> "Suspicious txn detected " + txn.getId());
                    break scan;                          // abandon whole scan
                }
            }
        }
        return suspicious;
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
